#[test]
fn wasmtime_smoke_sort_key_monotonic_agrees_with_compare() {
    let Some(h) = SmokeHarness::build_or_skip() else {
        return;
    };
    let (mut store, bindings) = h.instantiate();
    let collation = bindings.stringcheese_icu_collation_collation();
    // A small set of DE inputs where sort-key ordering should
    // agree with compare at tertiary — same predicate the
    // native `sort_key_compares_consistently_with_compare` test
    // covers.
    let strings = ["apple", "Baer", "Bär", "Muller", "Munk", "Straße"];
    for pair in strings.windows(2) {
        let a = pair[0];
        let b = pair[1];
        let ka = collation
            .call_sort_key(&mut store, a, &loc("de"), WitStrength::Tertiary)
            .expect("sort-key trap-free")
            .unwrap_or_else(|e| panic!("sort-key returned error: {}", describe_err(&e)));
        let kb = collation
            .call_sort_key(&mut store, b, &loc("de"), WitStrength::Tertiary)
            .expect("sort-key trap-free")
            .unwrap_or_else(|e| panic!("sort-key returned error: {}", describe_err(&e)));
        let key_ord = ka.cmp(&kb);
        let cmp_ord = collation
            .call_compare(&mut store, a, b, &loc("de"), WitStrength::Tertiary)
            .expect("compare trap-free")
            .unwrap_or_else(|e| panic!("compare returned error: {}", describe_err(&e)));
        let cmp_ord_std = match cmp_ord {
            WitOrdering::Less => std::cmp::Ordering::Less,
            WitOrdering::Equal => std::cmp::Ordering::Equal,
            WitOrdering::Greater => std::cmp::Ordering::Greater,
        };
        assert_eq!(
            key_ord, cmp_ord_std,
            "sort-key vs compare disagreed for ({a:?}, {b:?}) at tertiary",
        );
    }
}

#[test]
fn wasmtime_smoke_supported_locales_lists_bundled_tags() {
    let Some(h) = SmokeHarness::build_or_skip() else {
        return;
    };
    let (mut store, bindings) = h.instantiate();
    let caps = bindings.stringcheese_icu_collation_capabilities();
    let record = caps
        .call_get_capabilities(&mut store)
        .expect("get-capabilities trap-free");
    assert_eq!(
        record.supported_locales,
        vec![
            "en".to_string(),
            "de".to_string(),
            "fr".to_string(),
            "tr".to_string(),
            "ru".to_string(),
            "zh".to_string(),
        ],
    );
    assert!(
        matches!(record.max_strength, WitStrength::Identical),
        "max strength should be Identical, got {:?}",
        record.max_strength,
    );
    assert_eq!(record.cldr_version, "44.1");
}

